//! Board's look: egui visuals and styles built only from the generated token tables (`tokens.rs`,
//! generated by `build.rs` from `design/tokens/tokens.json`). Direction E: paper background, rules not
//! boxes, 0 radius on content and 5 px on controls, no shadows, crimson only as emphasis (never as
//! "down"), one accent for the focus ring. Light and dark come from `$value` and `news.dark`; the
//! theme follows Windows unless Karthik overrides it. No typeface files ship with egui, so the default
//! proportional face is used and the sizes come from the tokens.

use egui::{Color32, CornerRadius, FontFamily, FontId, Shadow, Stroke, TextStyle, Theme};

#[allow(dead_code)]
mod tokens {
    include!(concat!(env!("OUT_DIR"), "/tokens.rs"));
}

pub use tokens::{DARK, LIGHT, Palette, border, layout, radius, size, space};

/// The manual override beside "follow Windows".
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Preference {
    #[default]
    System,
    Light,
    Dark,
}

impl Preference {
    pub fn label(self) -> &'static str {
        match self {
            Preference::System => "Follow Windows",
            Preference::Light => "Light",
            Preference::Dark => "Dark",
        }
    }

    fn egui(self) -> egui::ThemePreference {
        match self {
            Preference::System => egui::ThemePreference::System,
            Preference::Light => egui::ThemePreference::Light,
            Preference::Dark => egui::ThemePreference::Dark,
        }
    }
}

pub fn palette(theme: Theme) -> &'static Palette {
    match theme {
        Theme::Light => &LIGHT,
        Theme::Dark => &DARK,
    }
}

fn c(rgb: [u8; 3]) -> Color32 {
    Color32::from_rgb(rgb[0], rgb[1], rgb[2])
}

/// The colours Board's own drawing uses, for the current mode.
#[derive(Debug, Clone, Copy)]
pub struct Tones {
    pub paper: Color32,
    pub wash: Color32,
    pub rule: Color32,
    pub ink: Color32,
    pub ink_2: Color32,
    pub ink_3: Color32,
    pub brand: Color32,
    pub error: Color32,
}

pub fn tones(theme: Theme) -> Tones {
    let p = palette(theme);
    Tones {
        paper: c(p.paper),
        wash: c(p.wash),
        rule: c(p.rule),
        ink: c(p.ink),
        ink_2: c(p.ink_2),
        ink_3: c(p.ink_3),
        brand: c(p.brand),
        error: c(p.error),
    }
}

/// The visuals of one mode.
pub fn visuals(theme: Theme) -> egui::Visuals {
    let p = palette(theme);
    let mut v = match theme {
        Theme::Light => egui::Visuals::light(),
        Theme::Dark => egui::Visuals::dark(),
    };
    let (paper, wash, rule, ink, ink_2) = (c(p.paper), c(p.wash), c(p.rule), c(p.ink), c(p.ink_2));
    let control = c(p.control_border);
    let hair = border::HAIRLINE;
    let ctl = CornerRadius::same(radius::CONTROL as u8);
    v.panel_fill = paper;
    v.window_fill = paper;
    v.extreme_bg_color = paper;
    v.faint_bg_color = wash;
    v.code_bg_color = wash;
    v.hyperlink_color = ink;
    v.warn_fg_color = ink;
    v.error_fg_color = c(p.error);
    v.window_shadow = Shadow::NONE;
    v.popup_shadow = Shadow::NONE;
    v.window_corner_radius = CornerRadius::same(radius::NONE as u8);
    v.menu_corner_radius = CornerRadius::same(radius::NONE as u8);
    v.window_stroke = Stroke::new(hair, rule);
    v.selection.bg_fill = c(p.selection);
    v.selection.stroke = Stroke::new(border::FOCUS, c(p.focus));
    v.override_text_color = None;
    v.widgets.noninteractive.bg_fill = paper;
    v.widgets.noninteractive.weak_bg_fill = paper;
    v.widgets.noninteractive.bg_stroke = Stroke::new(hair, rule);
    v.widgets.noninteractive.fg_stroke = Stroke::new(hair, ink);
    v.widgets.noninteractive.corner_radius = CornerRadius::same(radius::NONE as u8);
    for (w, fill, stroke) in [
        (&mut v.widgets.inactive, wash, control),
        (&mut v.widgets.hovered, wash, ink),
        (&mut v.widgets.active, rule, ink),
        (&mut v.widgets.open, wash, ink),
    ] {
        w.bg_fill = fill;
        w.weak_bg_fill = fill;
        w.bg_stroke = Stroke::new(hair, stroke);
        w.fg_stroke = Stroke::new(hair, ink);
        w.corner_radius = ctl;
        w.expansion = 0.0;
    }
    v.widgets.hovered.fg_stroke = Stroke::new(hair, ink);
    v.weak_text_color = Some(ink_2);
    v
}

/// Text sizes and spacing from the tokens (both modes share them).
pub fn style(s: &mut egui::Style) {
    let sans = FontFamily::Proportional;
    s.text_styles = [
        (TextStyle::Small, FontId::new(size::SOURCE, sans.clone())),
        (TextStyle::Body, FontId::new(size::UI, sans.clone())),
        (TextStyle::Button, FontId::new(size::UI, sans.clone())),
        (
            TextStyle::Heading,
            FontId::new(size::HEADLINE_S, sans.clone()),
        ),
        // No monospace face in the system: log lines and ids use the same face.
        (TextStyle::Monospace, FontId::new(size::LABEL, sans)),
    ]
    .into();
    s.spacing.item_spacing = egui::vec2(space::S3, space::S3);
    s.spacing.button_padding = egui::vec2(space::S4, space::S2);
    s.spacing.window_margin = egui::Margin::same(space::S5 as i8);
    s.spacing.interact_size.y = space::S7;
}

/// Install both themes and the preference. Call once at start.
pub fn install(ctx: &egui::Context, pref: Preference) {
    for t in [Theme::Light, Theme::Dark] {
        ctx.set_visuals_of(t, visuals(t));
        ctx.style_mut_of(t, style);
    }
    ctx.set_theme(pref.egui());
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;

    #[test]
    fn the_generated_palette_matches_the_tokens_in_both_modes() {
        // paper #F4F4F1 / #17181A and brand #C8213A / #F4687C (design/tokens/tokens.json).
        assert_eq!(LIGHT.paper, [0xF4, 0xF4, 0xF1]);
        assert_eq!(DARK.paper, [0x17, 0x18, 0x1A]);
        assert_eq!(LIGHT.brand, [0xC8, 0x21, 0x3A]);
        assert_eq!(DARK.brand, [0xF4, 0x68, 0x7C]);
        assert_eq!(radius::CONTROL, 5.0);
        assert_eq!(radius::NONE, 0.0);
        assert!((size::UI - 15.0).abs() < 0.01);
    }

    #[test]
    fn visuals_use_paper_ink_and_no_shadow() {
        for t in [Theme::Light, Theme::Dark] {
            let v = visuals(t);
            let p = palette(t);
            assert_eq!(v.panel_fill, c(p.paper));
            assert_eq!(v.widgets.noninteractive.fg_stroke.color, c(p.ink));
            assert_eq!(v.window_shadow, Shadow::NONE);
            assert_eq!(v.widgets.inactive.corner_radius, CornerRadius::same(5));
        }
        assert_ne!(
            visuals(Theme::Light).panel_fill,
            visuals(Theme::Dark).panel_fill
        );
    }

    /// The lint the issue asks for: no literal colours or sizes in Board code. Only `theme.rs` may
    /// build a `Color32`, and only from the generated tables.
    #[test]
    fn no_literal_colours_in_board_code() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
        let mut files = vec![dir.clone()];
        let mut seen = 0;
        while let Some(d) = files.pop() {
            for e in std::fs::read_dir(&d).unwrap() {
                let p = e.unwrap().path();
                if p.is_dir() {
                    files.push(p);
                    continue;
                }
                if p.extension().and_then(|x| x.to_str()) != Some("rs") {
                    continue;
                }
                seen += 1;
                let text = std::fs::read_to_string(&p).unwrap();
                let name = p.file_name().unwrap().to_string_lossy().into_owned();
                let hex = text
                    .match_indices('#')
                    .filter(|(i, _)| {
                        let rest = &text[i + 1..];
                        let h: String = rest.chars().take_while(char::is_ascii_hexdigit).collect();
                        h.len() == 6 || h.len() == 8
                    })
                    // Rust attributes and token docs in comments: look only at code lines.
                    .filter(|(i, _)| {
                        let line_start = text[..*i].rfind('\n').map_or(0, |n| n + 1);
                        !text[line_start..*i].trim_start().starts_with("//")
                    })
                    .count();
                assert_eq!(hex, 0, "{name}: a literal hex colour");
                if name != "theme.rs" {
                    for bad in [
                        "Color32::from_rgb",
                        "Color32::from_rgba",
                        "Color32::from_gray",
                        "Color32::from_black_alpha",
                        "Color32::from_white_alpha",
                        "Color32::WHITE",
                        "Color32::BLACK",
                        "Color32::RED",
                        "Color32::GREEN",
                        "Color32::BLUE",
                        "Color32::YELLOW",
                        "Color32::GRAY",
                        "Color32::LIGHT_",
                        "Color32::DARK_",
                        "rgb(",
                    ] {
                        assert!(!text.contains(bad), "{name}: {bad}");
                    }
                }
            }
        }
        assert!(seen >= 5);
    }
}
